/* Game data tables for the menus (data.c is generated by tools/gendata.py from
 * field_hashes.json, extra_fields.json, story.json and warps.json; don't edit it by hand). */
#ifndef DATA_H
#define DATA_H

#include <stdint.h>

typedef enum { FT_NONE, FT_INT, FT_BOOL, FT_ENUM, FT_FLOAT } field_type_t;
typedef struct { uint32_t hash; uint8_t type; } field_t;

/* inventory > items, in the game's item-screen order */
typedef enum { IK_ACQUIRED, IK_OWNED, IK_TRADE_CHILD, IK_TRADE_ADULT, IK_OCARINA } item_kind_t;
typedef struct {
  const char *label;
  uint8_t     kind;
  field_t     owned;     /* IK_OWNED: Int 0/1 */
  uint32_t    acquired;  /* Bool "has been acquired" (what the item screen needs) */
  const char *button;    /* item-button choice name, or NULL */
  uint32_t    worn_slot; /* GD_STR_* it's worn in, or 0 */
  const char *worn_item; /* PlayerStatus.Equip* value when worn */
} inv_item_t;

/* one-off pouch items (masks, trade items): count 1 + IsGet.<item> */
typedef struct { const char *label, *item, *button; } pouch_one_t;

typedef struct { const char *label; uint32_t count, cap; int32_t fixed; uint32_t acquired; } ammo_t;

/* a toggle over one or two fields set together (quest items, songs, dungeon items...) */
typedef struct { const char *label; field_t f[2]; uint32_t acquired; } flag_t;

typedef struct { const char *label; flag_t items[3]; } dungeon_t; /* map, compass, boss key */
typedef struct { const char *label; uint32_t hash; } number_t;

typedef struct { field_t own; uint32_t available, contents; } bottle_t;

typedef struct { const char *label; uint32_t hash; uint8_t n_stages; const char *const *stages; } quest_t;

/* warps */
enum { WC_CHILD, WC_ADULT, WC_DUNGEON, WC_BOSS, WC_OTHER, WC_COUNT };
/* starter: an actor in the map shares the spawn's name (an exit), which the standard arrival
 * event needs as its event starter (spawn_starters.json) */
typedef struct { const char *label, *pos, *event; uint8_t starter; } spawn_t;
typedef struct { const char *name, *label; uint8_t category, dungeon; uint16_t first, n; } warp_map_t;

extern const inv_item_t  data_items[];       extern const int data_n_items;
extern const inv_item_t  data_gear[];        extern const int data_n_gear;
extern const pouch_one_t data_masks[];       extern const int data_n_masks;
extern const pouch_one_t data_trade_child[]; extern const int data_n_trade_child;
extern const pouch_one_t data_trade_adult[]; extern const int data_n_trade_adult;
extern const ammo_t      data_ammo[];        extern const int data_n_ammo;
extern const flag_t      data_quest_items[]; extern const int data_n_quest_items;
extern const flag_t      data_songs[];       extern const int data_n_songs;
extern const dungeon_t   data_dungeons[];    extern const int data_n_dungeons;
extern const number_t    data_small_keys[];  extern const int data_n_small_keys;
extern const number_t    data_skulltulas;
extern const flag_t      data_double_defense, data_agony;
extern const bottle_t    data_bottles[5];
extern const char *const data_bottle_names[]; extern const uint32_t data_bottle_values[];
extern const uint32_t    data_bottle_acquired[]; extern const int data_n_bottle_contents;
extern const uint32_t    data_acquired_bottle;
extern const field_t     data_strength;       extern const uint32_t data_strength_values[4];
extern const field_t     data_diving_depth;   extern const float data_scale_depths[3];
extern const quest_t     data_quests[];      extern const int data_n_quests;
extern const uint32_t    data_action_guides[]; extern const int data_n_action_guides;
extern const uint32_t    data_action_guide_navi;
extern const char *const data_warp_categories[WC_COUNT];
extern const warp_map_t  data_warp_maps[];   extern const int data_n_warp_maps;
extern const spawn_t     data_spawns[];      extern const int data_n_spawns;

/* air walls (airwalls.json): a wall's world point for a local shape point p is t + R (s * p), with
 * R = Rz Ry Rx from r (radians), as sead's makeR (airwalls.py). */
enum { VOLUME_BLOCKER, VOLUME_OTHER_WALL, VOLUME_LOADING, VOLUME_VOID, VOLUME_HITBOX };
typedef struct { uint8_t type; float a[3], b[3]; float radius; } airshape_t; /* box: centre, half; cylinder: a, b, r */
typedef struct { float t[3], r[3], s[3]; uint16_t first_shape; uint8_t n_shapes, kind; } airwall_t;
typedef struct { const char *map; uint16_t first, n; } airmap_t;
extern const airshape_t  data_airshapes[];
extern const airwall_t   data_airwalls[];
extern const airmap_t    data_airmaps[];     extern const int data_n_airmaps;
extern const airmap_t    data_scene_maps[];  extern const int data_n_scene_maps;

#endif
